{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Lurtotecan, a complex fused heterocycle with polar/lactone features, had absolute oral bioavailability of only 11.3% ± 5.2 in patients, demonstrating that such polar fused systems can be poorly absorbed and supporting low F for the query's dianionic chromone-quinolone dicarboxylate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Dronedarone had an absolute oral bioavailability of only 4% in fasted humans, showing that even a lipophilic fused heterocycle can have very low systemic availability; this supports a low F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Eliglustat had a simulated absolute oral bioavailability of 0.086, providing another example of a complex heterocyclic drug with low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "YH4808 had low absolute oral bioavailability of 10.1% with high interindividual variability, supporting low F for a complex heterocyclic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Ofloxacin, a quinolone with a basic piperazine and fluorine, had absolute oral bioavailability >95% in healthy subjects; this high-F evidence is only weakly applicable to the query because the query lacks a basic center and is a dianionic dicarboxylate.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C66"],
      "claim": "Pefloxacin, another quinolone with a basic piperazine, showed complete absolute oral bioavailability; this is contradicted by the query's lack of a basic amine and its two ionizable carboxylic acids.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C56"],
      "claim": "Bumetanide, an anionic monocarboxylate, had absolute oral bioavailability of 0.72-0.96; however, the query's two carboxylates and absence of lipophilic/zwitterionic absorption-promoting groups make this high-F evidence less applicable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a dianionic chromone-quinolone dicarboxylic acid with no basic center, expected to have poor membrane permeability and low oral bioavailability. Low-F analogues support this, while high-F quinolone analogues are less applicable because their absorption depends on zwitterionic basic amines.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "No permeability or efflux-transporter data for the query.",
    "High-transfer quinolone analogues are zwitterionic, whereas the query is dianionic, making their high-F evidence mechanistically uncertain.",
    "Low-F analogues achieve low bioavailability through different mechanisms (e.g., first-pass metabolism vs permeability), so mechanism-specific transfer is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

